<?php $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<section class="directory-hero"><span class="eyebrow">ApPlanner perto de você</span><h1>Encontre estabelecimentos e horários disponíveis.</h1><p>Use sua localização apenas nesta busca ou informe um CEP. Sua posição não é armazenada.</p><div class="directory-search"><button class="btn btn-primary btn-lg" type="button" data-nearby-location>Usar minha localização</button><form method="get" action="/estabelecimentos"><label class="visually-hidden" for="directoryCep">CEP</label><input class="form-control form-control-lg" id="directoryCep" name="cep" inputmode="numeric" maxlength="9" placeholder="Digite seu CEP" value="<?=$e($cep)?>"><button class="btn btn-light btn-lg">Buscar por CEP</button></form></div><p class="directory-location-status" data-location-status><?=$e($locationMessage)?></p></section>
<section class="directory-results"><div class="section-heading"><div><span class="eyebrow">Agenda aberta</span><h2><?=count($establishments)?> estabelecimento(s) encontrado(s)</h2></div></div><div class="directory-grid"><?php foreach($establishments as $item):$address=implode(', ',array_filter([$item['address'],$item['address_number'],$item['district'],$item['city'],$item['state']]));$publicPath=(string)($item['public_path']??'/');$isArena=!empty($item['is_arena']);?><article class="directory-card"><div class="directory-card-head"><?php if($item['logo_path']):?><img src="<?=$e($item['logo_path'])?>" alt="Logo de <?=$e($item['name'])?>"><?php else:?><span style="--directory-brand:<?=$e($item['primary_color']?:'#3157d5')?>"><?=$e(mb_strtoupper(mb_substr($item['name'],0,1)))?></span><?php endif;?><div><small><?=$isArena?'Arena esportiva':$e($item['category']?:'Estabelecimento')?></small><h3><?=$e($item['name'])?></h3></div><?php if($item['distance_km']!==null):?><b><?=$e(number_format((float)$item['distance_km'],1,',','.'))?> km</b><?php endif;?></div><?php if($address):?><p class="directory-address">📍 <?=$e($address)?></p><?php endif;?><?php if($item['next_availability']):$next=$item['next_availability'];?><div class="directory-availability available"><span><?=$isArena?'Próximo horário livre':'Próxima vaga'?></span><strong><?=$e($next['date_label'])?> às <?=$e($next['time'])?></strong><small><?php if($isArena):?><?=$e($next['court']??$next['professional'])?> · <?=$e($next['modality']??$next['service'])?><?php else:?><?=$e($next['service'])?> com <?=$e($next['professional'])?><?php endif;?></small></div><a class="btn btn-primary w-100" href="<?=$e($publicPath)?><?=$isArena?'':'#agendar'?>"><?=$isArena?'Reservar quadra':'Ver horários e agendar'?></a><?php else:?><div class="directory-availability full"><span>Sem horários nos próximos dias</span><strong><?=$isArena?'Consulte outras datas':'Agenda preenchida'?></strong><small><?=$isArena?'A Arena pode possuir horários fora da janela consultada.':($item['waitlist_enabled']?'Você pode entrar na lista de espera.':'Consulte o estabelecimento.')?></small></div><a class="btn btn-primary w-100" href="<?=$e($publicPath)?><?=$isArena?'':'#agendar'?>">Abrir <?=$isArena?'Arena':'estabelecimento'?></a><?php endif;?></article><?php endforeach;?><?php if(!$establishments):?><div class="empty-state">Nenhum estabelecimento público foi encontrado.</div><?php endif;?></div></section>
